"""Clean-room AsyncEngine stubs."""


class _AsyncTransactionContext:
    async def __aenter__(self):
        return self

    async def __aexit__(self, *args):
        pass


class AsyncEngine:
    def begin(self, *args, **kwargs) -> _AsyncTransactionContext:
        return _AsyncTransactionContext()

    def connect(self, *args, **kwargs) -> _AsyncTransactionContext:
        return _AsyncTransactionContext()


def create_async_engine(*args, **kwargs) -> AsyncEngine:
    return AsyncEngine()
